// beloved.mjs — the JavaScript (Node ESM) client for the Lovers (VI) binding.
// Generated by @necro/grimoires-lovers-js ast-bridge (pure, deterministic).
// It does NOT reimplement the Python logic: every call forwards args over the
// pinned JSON-lines contract to the one long-lived heart.py child.
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const HEART = join(__dirname, "heart.py");
const PYTHON = process.env.PYTHON ?? "python3";

let _child = null;
let _nextId = 1;
let _buffer = "";
const _pending = new Map();

/** Spawn (once) the long-lived python heart and wire its stdout to replies. */
function _ensureChild() {
  if (_child !== null) return _child;
  _child = spawn(PYTHON, [HEART], { stdio: ["pipe", "pipe", "inherit"] });
  _child.stdout.setEncoding("utf8");
  _child.stdout.on("data", (chunk) => {
    _buffer += chunk;
    let nl;
    while ((nl = _buffer.indexOf("\n")) !== -1) {
      const line = _buffer.slice(0, nl);
      _buffer = _buffer.slice(nl + 1);
      if (line.trim().length === 0) continue;
      _onReply(JSON.parse(line));
    }
  });
  _child.on("exit", () => {
    for (const { reject } of _pending.values()) {
      reject(new Error("heart exited before replying"));
    }
    _pending.clear();
    _child = null;
  });
  return _child;
}

/** Resolve/reject the pending promise correlated to this reply's id. */
function _onReply(reply) {
  const slot = _pending.get(reply.id);
  if (slot === undefined) return;
  _pending.delete(reply.id);
  if (reply.ok === true) {
    slot.resolve(reply.value);
  } else {
    const err = new Error(reply.error ? reply.error.message : "unknown error");
    err.name = reply.error ? reply.error.type : "Error";
    slot.reject(err);
  }
}

/** Send one request over the contract and await its correlated reply. */
function _call(fn, args) {
  const child = _ensureChild();
  const id = _nextId++;
  const line = JSON.stringify({ id, fn, args });
  return new Promise((resolve, reject) => {
    _pending.set(id, { resolve, reject });
    child.stdin.write(line + "\n");
  });
}

/** Terminate the long-lived heart child (releases the binding). */
export function close() {
  if (_child !== null) {
    _child.stdin.end();
    _child.kill();
    _child = null;
  }
}

/**
 * normalize_command — forwards to the resurrected Python function over the contract.
 * @param {string} raw
 * @returns {Promise<string>}
 */
export async function normalize_command(raw) {
  if (raw === undefined) throw new TypeError("normalize_command: required argument \"raw\" is missing");
  return _call("normalize_command", { raw: raw });
}
/**
 * charge_level — forwards to the resurrected Python function over the contract.
 * @param {number} battery
 * @param {number} capacity
 * @returns {Promise<number>}
 */
export async function charge_level(battery, capacity) {
  if (battery === undefined) throw new TypeError("charge_level: required argument \"battery\" is missing");
  if (capacity === undefined) throw new TypeError("charge_level: required argument \"capacity\" is missing");
  return _call("charge_level", { battery: battery, capacity: capacity });
}
/**
 * can_move — forwards to the resurrected Python function over the contract.
 * @param {string} direction
 * @param {Array<*>} exits
 * @param {boolean} locked
 * @returns {Promise<boolean>}
 */
export async function can_move(direction, exits, locked) {
  if (direction === undefined) throw new TypeError("can_move: required argument \"direction\" is missing");
  if (exits === undefined) throw new TypeError("can_move: required argument \"exits\" is missing");
  return _call("can_move", { direction: direction, exits: exits, locked: locked });
}